content.text:
            start = 0
            stop = size
            a = path[0]
            b = path[1]
            if ((a, b) if a < b else (b, a)) in marked:
                start = 1
            a = path[size - 2]
            b = path[size - 1]
            if ((a, b) if a < b else (b, a)) in marked:
                stop = size - 1
            if stop - start >= 2:
                key = path[start:stop]
                trimmed[key] = trimmed.get(key, 0) + count
        current = trimmed
    return round_of, current


