def collect_groups(core_paths, var_of, count):
    """Group core observations per link into (left literal, right literal).

    A literal is (0, constant type, False) or (1, variable, reversed flag).
    Also returns one scope per variable: the center plus every distinct
    nonconstant context variable, as required by the width promise.
    """
    groups = [None] * count
    for path, count_value in core_paths.items():
        size = len(path)
        for i in range(size - 1):
            a = path[i]
            b = path[i + 1]
            if a < b:
                left = (path[i - 1], a) if i > 0 else None
                right = (b, path[i + 2]) if i + 2 < size else None
                var = var_of[(a, b)]
            else:
                left = (path[i + 2], b) if i + 2 < size else None
                right = (a, path[i - 1]) if i > 0 else None
                var = var_of[(b, a)]
            if left is None:
                lit_l = (0, 0, False)
            else:
                x, y = left
                lit_l = (1, var_of[canon(x, y)], x > y)
            if right is None:
                lit_r = (0, 2, False)
            else:
                x, y = right
                lit_r = (1, var_of[canon(x, y)], x > y)
            slot = groups[var]
            if slot is None:
                slot = groups[var] = {}
            pair = (lit_l, lit_r)
            slot[pair] = slot.get(pair, 0) + count_value

    scopes = []
    for var in range(count):
        slot = groups[var]
        if slot is None:
            # a core link always has at least one observation
            raise Invalid('core link without context')
        ctx = set()
        for (lit_l, lit_r) in slot:
            if lit_l[0] == 1:
                ctx.add(lit_l[1])
            if lit_r[0] == 1:
                ctx.add(lit_r[1])
        ctx.discard(var)
        scopes.append(tuple([var] + sorted(ctx)))
    return groups, scopes


def build_tables(groups, scopes):
    """phi_e tables: one integer per joint assignment of the scope."""
    factors = []
    for var in range(len(scopes)):
        scope = scopes[var]
        width = len(scope)
        size = POW3[width]
        digits = [[(idx // POW3[j]) % 3 for idx in range(size)]
                  for j in range(width)]
        center = digits[0]
        positions = {}
        for j in range(1, width):
            positions[scope[j]] = j
        table = [0] * size
        for (lit_l, lit_r), count in groups[var].items():
            if lit_l[0] == 0:
                left = None
                lconst = lit_l[1]
            else:
                col = digits[positions[lit_l[1]]]
                left = [2 - d for d in col] if lit_l[2] else col
                lconst = 0
            if lit_r[0] == 0:
                right = None
                rconst = lit_r[1]
            else:
                col = digits[positions[lit_r[1]]]
                right = [2 - d for d in col] if lit_r[2] else col
                rconst = 0
            if left is None and right is None:
                want = GTAB[lconst * 3 + rconst]
                for idx in range(size):
                    if center[idx] == want:
                        table[idx] += count
            elif left is None:
                for idx in range(size):
                    if center[idx] == GTAB[lconst * 3 + right[idx]]:
                        table[idx] += count
            elif right is None:
                for idx in range(size):
